3 red tests actually — good. Also let me check "minúscula" and "com espaço" passed (they're green-born positive sides, fine). Now implement the código validation:

```js
function normalizarCodigo(codigo) {
  return codigo.replace(/\s+/g, '').toUpperCase()
}

function codigoEhValido(encontroId, codigo, instante) {
  const normalizado = normalizarCodigo(codigo)
  if (normalizado.length !== 6 || [...normalizado].some(c => !ALFABETO.includes(c))) {
    return false
  }
  const ms = Date.parse(instante)
  const atual = codigoDoMinuto(encontroId, new Date(ms).toISOString())
  const anterior = codigoDoMinuto(encontroId, new Date(ms - MINUTO).toISOString())
  return normalizado === atual || normalizado === anterior
}
```

Then in registrarPresenca, replace creation: validate before creating.

```js
const instante = agora()
if (!dentroDaJanela(instante, encontro.inicio)) return { erro: 'FORA_DA_JANELA' }
if (!codigoEhValido(encontro.id, codigo, instante)) return { erro: 'CODIGO_INVALIDO' }
```
AND remove the unused `codigo` parameter issue — currently signature has `codigo` param unused; now it will be used.

